window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[1]=[{"id":"01_19","g":1,"l":19,"topic":"Рестораны и кафе","module":"Страна бизнеса","format":"Комбинированный","skills":["Командная работа","Работа с клиентом"],"goal":"К концу урока ученик сможет назвать 4 работника кафе (повар, официант, кассир, уборщик) и сказать, что делает каждый.","criteria":["Я называю, кто работает в кафе.","Я говорю, что делает каждый работник.","Я объясняю, зачем кафе нужно людям."],"result":"Плакат «Команда нашего кафе»: 4 работника с рисунком и одним действием каждого.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Кафе (cafe)","real":"Место, где готовят еду и угощают гостей за деньги","shown":"Место, где готовят еду и угощают гостей за деньги","truth":true,"first":"К"},{"term":"Меню","real":"Список блюд и напитков с ценами","shown":"Человек, который пришёл в кафе покушать","truth":false,"first":"М"},{"term":"Повар","real":"Работник, который готовит еду","shown":"Работник, который готовит еду","truth":true,"first":"П"},{"term":"Официант","real":"Работник, который принимает заказ и приносит еду гостю","shown":"Список блюд и напитков с ценами","truth":false,"first":"О"},{"term":"Кассир","real":"Работник, который берёт оплату","shown":"Работник, который берёт оплату","truth":true,"first":"К"},{"term":"Гость (клиент)","real":"Человек, который пришёл в кафе покушать","shown":"Работник, который принимает заказ и приносит еду гостю","truth":false,"first":"Г"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Кафе (cafe)","def":"Место, где готовят еду и угощают гостей за деньги"},{"term":"Меню","def":"Список блюд и напитков с ценами"},{"term":"Повар","def":"Работник, который готовит еду"},{"term":"Официант","def":"Работник, который принимает заказ и приносит еду гостю"},{"term":"Кассир","def":"Работник, который берёт оплату"},{"term":"Гость (клиент)","def":"Человек, который пришёл в кафе покушать"}],"english":"cafe — кафе; business — бизнес","concepts":{"head":"Понятия","items":["Кафе (cafe) — место, где люди едят еду, которую для них приготовили.","Это бизнес (business): кафе продаёт готовую еду и услугу — обслуживание.","Меню — список блюд с ценами."]},"steps":{"head":"Как это работает","items":["Гость приходит и садится за стол","Официант даёт меню и записывает заказ","Повар готовит блюдо","Официант приносит еду","Гость платит кассиру","Уборщик убирает стол для следующего гостя. Если один работник не сделает свою часть, гость останется недоволен"]},"scheme":"Круг из 4 стрелок: «Официант берёт заказ» → «Повар готовит» → «Официант приносит» → «Кассир берёт оплату» → снова к гостю. В центре — рисунок гостя с улыбкой.","examples":[{"lab":"Казахстан","text":"В кафе национальной кухни гость заказал баурсаки за 10 условных тенге и чай за 5 условных тенге — всего 15 условных тенге. Повар пожарил баурсаки, официант принёс, кассир взял оплату."},{"lab":"Мир","text":"В Италии есть маленькие кафе-пиццерии, где повар печёт пиццу прямо при гостях."}],"mistake":{"myth":"Дети говорят, что в кафе работает только повар","fix":"Разыграть сценку без официанта — гость не знает, что заказать, и еда не доходит до стола; значит, нужна вся команда."},"check":[{"q":"Кто готовит еду?","a":"Повар"},{"q":"Что даёт официант гостю сначала?","a":"Меню"},{"q":"Зачем людям кафе?","a":"Покушать, когда нет времени готовить, отметить праздник, встретиться с друзьями"}],"kz":{"text":"Казахская национальная кухня в кафе: во многих городах Казахстана есть кафе, где подают бешбармак, баурсаки и чай с молоком.","link":"кафе продаёт не только еду, но и традицию — гости из других стран приходят попробовать казахские блюда."},"world":{"text":"Во многих странах мира стараются не выбрасывать еду: в некоторых кафе остатки отдают тем, кому нужна помощь, — это связано с ЦУР ООН № 12 «Ответственное потребление».","link":""},"fact":"Слово «ресторан» появилось во Франции больше 200 лет назад: так называли заведения, где подавали восстанавливающий силы бульон. Позже так стали называть все места, где можно заказать еду по меню.","cards":[{"n":"1","title":"Роли в кафе","lines":["Гость: садится, читает меню, вежливо заказывает 1 блюдо и 1 напиток.","Официант: здоровается, даёт меню, записывает заказ, приносит еду.","Повар: «готовит» блюдо (рисует его на тарелке из бумаги).","Кассир: называет цену по меню и берёт оплату условными тенге.","Меню: баурсаки — 10 тенге, плов — 20 тенге, чай — 5 тенге, сок — 5 тенге."],"hand":"Сдать: проигранную сценку (показ тренеру).","answers":[]},{"n":"2","title":"Плакат «Команда нашего кафе»","lines":["Нарисуйте 4 работников кафе. Под каждым напишите или скажите, что он делает.","Придумайте название кафе."],"hand":"Сдать: плакат группы.","answers":[]}],"homework":"Дома вместе с родителями нарисовать меню своего «домашнего кафе» из 3 блюд, которые готовят в семье.","support":"Картинки работников с подписями и готовые фразы: «Повар готовит», «Официант приносит», «Кассир берёт оплату»; ребёнок выбирает роль гостя или официанта с подсказкой.","advanced":"Придумать пятого работника кафе (например, курьер или администратор) и объяснить, зачем он нужен и что будет без него.","photo":{"src":"lessons/img/01_19.jpg","author":"Jason Leung","q":["Что вы видите на фото? Как это связано с нашей темой?","Что может сделать кафе, чтобы еда не пропадала?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l19.pptx","name":"19. Рестораны и кафе (1 кл).pptx","mb":1.5}},{"id":"01_20","g":1,"l":20,"topic":"Рестораны и кафе: практикум","module":"Страна бизнеса","format":"Проектная мастерская","skills":["Командная работа","Финансовое мышление","Работа с клиентом"],"goal":"К концу урока команда сможет составить меню кафе из 3 блюд с ценами в условных тенге и разыграть заказ, посчитав сумму до 100.","criteria":["Я вместе с командой составляю меню из 3 блюд с ценами.","Я правильно считаю сумму заказа.","Я вежливо принимаю или делаю заказ."],"result":"Меню кафе команды: название, 3 блюда с рисунками и ценами в условных тенге + разыгранный заказ с подсчётом суммы.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Меню","real":"Список блюд и напитков с ценами","shown":"Список блюд и напитков с ценами","truth":true,"first":"М"},{"term":"Цена","real":"Сколько тенге нужно заплатить за блюдо","shown":"Место, где готовят еду и угощают гостей за деньги","truth":false,"first":"Ц"},{"term":"Заказ","real":"То, что гость попросил приготовить","shown":"То, что гость попросил приготовить","truth":true,"first":"З"},{"term":"Сумма","real":"Сколько всего нужно заплатить за весь заказ","shown":"Сколько тенге нужно заплатить за блюдо","truth":false,"first":"С"},{"term":"Практика (practice)","real":"Когда мы пробуем сделать сами то, что узнали","shown":"Когда мы пробуем сделать сами то, что узнали","truth":true,"first":"П"},{"term":"Кафе (cafe)","real":"Место, где готовят еду и угощают гостей за деньги","shown":"Сколько всего нужно заплатить за весь заказ","truth":false,"first":"К"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Меню","def":"Список блюд и напитков с ценами"},{"term":"Цена","def":"Сколько тенге нужно заплатить за блюдо"},{"term":"Заказ","def":"То, что гость попросил приготовить"},{"term":"Сумма","def":"Сколько всего нужно заплатить за весь заказ"},{"term":"Практика (practice)","def":"Когда мы пробуем сделать сами то, что узнали"},{"term":"Кафе (cafe)","def":"Место, где готовят еду и угощают гостей за деньги"}],"english":"cafe — кафе; practice — практика","concepts":{"head":"Понятия","items":["Меню — список блюд с ценами.","Цена — сколько стоит одно блюдо.","Сумма заказа — сколько гость платит за всё вместе.","Практика (practice) — пробуем сами."]},"steps":{"head":"Как составить меню, по шагам","items":["Придумать название кафе","Выбрать 3 блюда (одно главное, одно лёгкое, один напиток)","Нарисовать каждое блюдо","Поставить цену в условных тенге: дороже то, на что нужно больше продуктов и труда","Проверить, что меню понятно гостю"]},"scheme":"Таблица из трёх строк: «Блюдо — Рисунок — Цена». Под таблицей пример: «Заказ: плов + чай = 30 + 5 = 35 тенге».","examples":[{"lab":"Казахстан","text":"Кафе «Дастархан»: плов — 30 тенге, баурсаки — 10 тенге, чай — 5 тенге. Гость заказал плов и чай: 30 + 5 = 35 условных тенге."},{"lab":"Мир","text":"В кафе в Японии часто ставят на витрину модели блюд, чтобы гость видел, что заказывает."}],"mistake":{"myth":"Дети ставят цены 1000 или «миллион»","fix":"Напомнить, что мы считаем до 100, и сравнить: если чай стоит 5 тенге, то плов не может стоить 1000 — гость не купит."},"check":[{"q":"Что должно быть в меню?","a":"Названия блюд и цены"},{"q":"Сколько стоят баурсаки и чай вместе?","a":"10 + 5 = 15 тенге"},{"q":"Почему плов дороже чая?","a":"Нужно больше продуктов и времени"}],"kz":{"text":"Казахские блюда в меню кафе: бешбармак, баурсаки, плов, кумыс и чай с молоком подают в кафе по всему Казахстану.","link":"меню показывает, чем кафе отличается от других."},"world":{"text":"Во всём мире в меню пишут цену заранее, чтобы гость знал, сколько заплатит, — это честно по отношению к покупателю. В некоторых странах в меню также рисуют значки «острое» или «без мяса», чтобы каждый гость выбрал подходящее.","link":""},"fact":"В Японии больше ста лет назад начали делать восковые, а потом пластиковые модели блюд для витрин кафе, чтобы гости сразу видели, как выглядит еда. Их называют «сампуру».","cards":[{"n":"1","title":"Наше меню","lines":["1) Придумайте название кафе.","2) Выберите 3 блюда: главное блюдо, лёгкое блюдо, напиток. Нарисуйте их.","3) Поставьте цену каждому блюду: от 5 до 50 условных тенге.","Подсказка: напиток дешевле, главное блюдо дороже."],"hand":"Сдать: меню на листе А4.","answers":[]},{"n":"2","title":"Считаем заказ","lines":["Меню для тренировки: лагман — 30 тенге, самса — 15 тенге, чай — 5 тенге, компот — 10 тенге.","Заказ 1: лагман + чай = ?","Заказ 2: самса + компот = ?","Заказ 3: самса + самса + чай = ?","Ответы для тренера: 35, 25, 35 тенге."],"hand":"Сдать: карточку с ответами.","answers":[]}],"homework":"Посчитать с родителями: сколько стоил бы заказ из 2 блюд в твоём меню; записать пример сложения.","support":"Готовые картинки блюд с ценами 5, 10, 20 тенге и числовая линейка до 50 для подсчёта суммы.","advanced":"Добавить в меню четвёртое блюдо и придумать «комбо» из двух блюд, которое стоит на 5 тенге дешевле, чем по отдельности; посчитать его цену.","photo":{"src":"lessons/img/01_20.jpg","author":"Sandra Seitamaa","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие значки можно добавить в наше меню?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l20.pptx","name":"20. Рестораны и кафе — практикум (1 кл).pptx","mb":1.5}},{"id":"01_21","g":1,"l":21,"topic":"Традиции родного края","module":"Страна бизнеса","format":"Комбинированный","skills":["Презентация","Критическое мышление"],"goal":"К концу урока ученик сможет рассказать в 2–3 предложениях об одной традиции своей семьи или края и назвать, что для неё нужно купить или сделать.","criteria":["Я называю одну традицию своей семьи или края.","Я рассказываю о ней 2–3 предложения.","Я называю, какой товар или услуга нужны для этой традиции."],"result":"Рисунок-рассказ «Наша традиция»: рисунок одной традиции и 2–3 предложения о ней с одним товаром или услугой, которые для неё нужны.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Традиция","real":"То, что семья или народ делает много лет и передаёт детям","shown":"То, что семья или народ делает много лет и передаёт детям","truth":true,"first":"Т"},{"term":"Праздник","real":"Особый день, который отмечают вместе","shown":"Дело, которое делает товары или услуги для людей","truth":false,"first":"П"},{"term":"Дастархан","real":"Праздничный стол, за которым угощают гостей","shown":"Праздничный стол, за которым угощают гостей","truth":true,"first":"Д"},{"term":"Гостеприимство","real":"Когда гостей встречают тепло и угощают","shown":"Особый день, который отмечают вместе","truth":false,"first":"Г"},{"term":"Команда (team)","real":"Люди, которые делают общее дело вместе","shown":"Люди, которые делают общее дело вместе","truth":true,"first":"К"},{"term":"Бизнес (business)","real":"Дело, которое делает товары или услуги для людей","shown":"Когда гостей встречают тепло и угощают","truth":false,"first":"Б"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Традиция","def":"То, что семья или народ делает много лет и передаёт детям"},{"term":"Праздник","def":"Особый день, который отмечают вместе"},{"term":"Дастархан","def":"Праздничный стол, за которым угощают гостей"},{"term":"Гостеприимство","def":"Когда гостей встречают тепло и угощают"},{"term":"Команда (team)","def":"Люди, которые делают общее дело вместе"},{"term":"Бизнес (business)","def":"Дело, которое делает товары или услуги для людей"}],"english":"business — бизнес; team — команда","concepts":{"head":"Понятия","items":["Традиция — то, что делают из года в год и передают от бабушек и дедушек детям.","Например, накрывать дастархан для гостей, праздновать Наурыз, проводить обряд тұсау кесу, когда малыш делает первые шаги."]},"steps":{"head":"Как традиция связана с бизнесом (business), по шагам","items":["Семья готовится к традиции","Ей нужны товары — продукты, одежда, подарки","Нужны услуги — фотограф, пекарь, ведущий праздника","Эти товары и услуги делают предприниматели. Так традиции дают работу многим людям"]},"scheme":"Слева — рисунок «Традиция» (юрта или дастархан). Стрелка к двум кругам: «Товары» (продукты, одежда) и «Услуги» (фотограф, пекарь). Ниже — человечки «Бизнес».","examples":[{"lab":"Казахстан","text":"На Наурыз семья варит наурыз-коже. Для этого покупают 7 продуктов: мясо, молоко, воду, соль, рис, пшено, пшеницу. Если каждый стоит 5 условных тенге, то всё вместе — 35 условных тенге."},{"lab":"Мир","text":"В Японии есть традиция чайной церемонии; для неё делают особые чашки, и мастера продают их по всему миру."}],"mistake":{"myth":"Дети называют традицией то, что было один раз («ходили в кино»)","fix":"Спросить «Это делали бабушки и дедушки? Будете делать каждый год?» — если нет, это событие, а не традиция."},"check":[{"q":"Что такое традиция?","a":"Что делают много лет и передают детям"},{"q":"Какой товар нужен для Наурыза?","a":"Продукты для наурыз-коже"},{"q":"Кто зарабатывает на празднике?","a":"Пекари, продавцы, фотографы"}],"kz":{"text":"Казахская юрта. Умение делать юрту — традиционное ремесло казахского народа, и сегодня мастера изготавливают юрты для праздников, туристических баз и музеев.","link":"старая традиция стала делом, которое кормит мастеров."},"world":{"text":"В разных странах есть свои праздничные традиции: в Японии — чайная церемония, в Китае — Новый год по лунному календарю с красными фонариками. Вокруг таких традиций работают мастера, магазины и кафе.","link":""},"fact":"Знания и умения изготовления казахской и кыргызской юрты внесены ЮНЕСКО в список нематериального культурного наследия человечества в 2014 году.","cards":[{"n":"1","title":"Что нужно для традиции?","lines":["Традиции: Наурыз, дастархан для гостей, тұсау кесу.","Товары и услуги: баурсаки, белая верёвочка, наурыз-коже, фотограф, чай, праздничная одежда.","Соедини каждую традицию с 2 товарами или услугами."],"hand":"Сдать: карточку с линиями.","answers":[]},{"n":"2","title":"Наша традиция","lines":["Нарисуй традицию своей семьи или края.","Расскажи по образцу: «В нашей семье есть традиция … . Мы делаем … . Для неё нужно купить …»"],"hand":"Сдать: рисунок.","answers":[]}],"homework":"Расспросить бабушку или дедушку об одной традиции семьи и рассказать её на следующем уроке.","support":"Картинки трёх традиций с подписями и опорная фраза: «В нашей семье есть традиция … . Для неё нужно … .»","advanced":"Придумать, какой маленький бизнес может помогать этой традиции (например, пекарня баурсаков к праздникам), и нарисовать его вывеску.","photo":{"src":"lessons/img/01_21.jpg","author":"T Y","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую нашу традицию было бы интересно показать детям из другой страны?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l21.pptx","name":"21. Традиции родного края (1 кл).pptx","mb":1.4}},{"id":"01_22","g":1,"l":22,"topic":"Праздники и ярмарки родного края: что на них продают","module":"Страна бизнеса","format":"Симуляция, ярмарка","skills":["Командная работа","Работа с клиентом","Финансовое мышление"],"goal":"К концу урока ученик сможет назвать 3 товара, которые продают на празднике или ярмарке, и объяснить, почему их покупают.","criteria":["Я называю товары, которые продают на празднике.","Я объясняю, почему их покупают.","Я честно продаю и считаю тенге."],"result":"Праздничный прилавок команды: 3 товара-рисунка с ценами в условных тенге и фраза продавца «Купите, потому что …».","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ярмарка (fair)","real":"Большой праздничный рынок, где продают много разных товаров","shown":"Большой праздничный рынок, где продают много разных товаров","truth":true,"first":"Я"},{"term":"Продажи (sales)","real":"Когда продавец отдаёт товар, а покупатель платит деньги","shown":"Стол, на котором продавец показывает товар","truth":false,"first":"П"},{"term":"Традиция","real":"То, что люди делают много лет и передают детям","shown":"То, что люди делают много лет и передают детям","truth":true,"first":"Т"},{"term":"Праздник","real":"Особый день, который отмечают вместе","shown":"Когда продавец отдаёт товар, а покупатель платит деньги","truth":false,"first":"П"},{"term":"Сувенир","real":"Подарок на память о празднике или месте","shown":"Подарок на память о празднике или месте","truth":true,"first":"С"},{"term":"Прилавок","real":"Стол, на котором продавец показывает товар","shown":"Особый день, который отмечают вместе","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Большой праздничный рынок, где продают много разных товаров"},{"term":"Продажи (sales)","def":"Когда продавец отдаёт товар, а покупатель платит деньги"},{"term":"Традиция","def":"То, что люди делают много лет и передают детям"},{"term":"Праздник","def":"Особый день, который отмечают вместе"},{"term":"Сувенир","def":"Подарок на память о празднике или месте"},{"term":"Прилавок","def":"Стол, на котором продавец показывает товар"}],"english":"fair — ярмарка; sales — продажи","concepts":{"head":"Понятия","items":["Ярмарка (fair) — праздничный рынок.","Продажи (sales) — обмен товара на деньги.","На празднике люди покупают то, что делает праздник радостным: угощения, подарки, украшения."]},"steps":{"head":"Как это работает","items":["Продавец узнаёт, какой праздник будет","Готовит подходящий товар","Красиво раскладывает его на прилавке","Говорит покупателю, почему товар нужен","Берёт оплату и благодарит"]},"scheme":"Три столбика: «Праздник» → «Что покупают» → «Почему покупают». Пример: Наурыз → баурсаки → угостить гостей; Новый год → ёлочные игрушки → украсить дом; День города → шарики → радость детям.","examples":[{"lab":"Казахстан","text":"На Наурыз продают баурсаки, наурыз-коже, сувениры с орнаментом. Мастер сделал 10 магнитов-юрт и продал по 5 условных тенге — получил 50 условных тенге."},{"lab":"Мир","text":"В Германии перед Новым годом и Рождеством работают праздничные ярмарки, где продают игрушки, пряники и горячие напитки."}],"mistake":{"myth":"Дети предлагают продавать на празднике всё подряд (например, кастрюли)","fix":"Спросить «Этот товар делает праздник радостнее? Его захотят купить именно сегодня?»"},"check":[{"q":"Что продают на Наурыз?","a":"Баурсаки, сувениры, коже"},{"q":"Почему на празднике покупают сувениры?","a":"На память, в подарок"},{"q":"Что делает продавец после оплаты?","a":"Благодарит покупателя"}],"kz":{"text":"Наурыз в Казахстане. В дни Наурыза в городах ставят юрты, проходят ярмарки, продают баурсаки, коже, сувениры и игрушки.","link":"праздник создаёт спрос на особые товары, и мастера готовятся к нему заранее."},"world":{"text":"Во многих странах проходят праздничные ярмарки: в Германии — рождественские, в Турции — базары на праздники. Мастера и фермеры продают там свои товары и получают доход.","link":""},"fact":"Наурыз внесён ЮНЕСКО в список нематериального культурного наследия человечества, его отмечают во многих странах, в том числе в Казахстане.","cards":[{"n":"1","title":"Наш праздничный прилавок","lines":["Праздник: ________ (Наурыз, Новый год или День города).","Нарисуйте 3 товара для этого праздника. Поставьте цену каждому: 5, 10, 15 или 20 тенге.","Придумайте фразу продавца: «Купите …, потому что …»."],"hand":"Сдать: 3 товара с ценами.","answers":[]},{"n":"2","title":"Считаем продажи","lines":["Сколько товаров мы продали? ____","Сколько тенге получили? Сложите все монеты: ____","Какой товар купили больше всего? ____ Почему? ____"],"hand":"Сдать: заполненную карточку.","answers":[]}],"homework":"Вспомнить с родителями, что покупали на последний праздник, и нарисовать один такой товар.","support":"Готовые картинки праздничных товаров с ценами 5 и 10 тенге и фраза-подсказка для продавца.","advanced":"Придумать новый праздничный товар, которого нет на ярмарке, и объяснить, почему его купят.","photo":{"src":"lessons/img/01_22.jpg","author":"Dex Ezekiel","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой товар из Казахстана понравился бы гостям ярмарки в другой стране?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l22.pptx","name":"22. Праздники и ярмарки родного края — что на них продают (1 кл).pptx","mb":1.5}},{"id":"01_23","g":1,"l":23,"topic":"Туризм: чем наш край интересен гостям","module":"Страна бизнеса","format":"Комбинированный","skills":["Презентация","Работа с клиентом"],"goal":"К концу урока ученик сможет назвать 2 места своего края, куда можно пригласить туриста, и что туристу там купить.","criteria":["Я называю 2 интересных места нашего края.","Я говорю, что турист может там купить.","Я приглашаю гостя вежливо и понятно."],"result":"Мини-буклет «Приглашаем в гости»: 2 места края и 1 товар или услуга для туриста в каждом.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Туризм (tourism)","real":"Путешествия, чтобы увидеть новые места и отдохнуть","shown":"Путешествия, чтобы увидеть новые места и отдохнуть","truth":true,"first":"Т"},{"term":"Турист","real":"Человек, который приехал посмотреть новое место","shown":"Подарок на память о месте","truth":false,"first":"Т"},{"term":"Туристический объект","real":"Место, которое интересно посмотреть: горы, озеро, музей","shown":"Место, которое интересно посмотреть: горы, озеро, музей","truth":true,"first":"Т"},{"term":"Активный отдых","real":"Отдых в движении: походы, лыжи, катание на лошади","shown":"Человек, который приехал посмотреть новое место","truth":false,"first":"А"},{"term":"Пассивный отдых","real":"Спокойный отдых: экскурсия, музей, отдых у озера","shown":"Спокойный отдых: экскурсия, музей, отдых у озера","truth":true,"first":"П"},{"term":"Сувенир","real":"Подарок на память о месте","shown":"Отдых в движении: походы, лыжи, катание на лошади","truth":false,"first":"С"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Туризм (tourism)","def":"Путешествия, чтобы увидеть новые места и отдохнуть"},{"term":"Турист","def":"Человек, который приехал посмотреть новое место"},{"term":"Туристический объект","def":"Место, которое интересно посмотреть: горы, озеро, музей"},{"term":"Активный отдых","def":"Отдых в движении: походы, лыжи, катание на лошади"},{"term":"Пассивный отдых","def":"Спокойный отдых: экскурсия, музей, отдых у озера"},{"term":"Сувенир","def":"Подарок на память о месте"}],"english":"tourism — туризм; business — бизнес","concepts":{"head":"Понятия","items":["Туризм (tourism) — путешествия ради отдыха и новых впечатлений.","Турист — гость, который приехал посмотреть край.","Туристический объект — интересное место.","Отдых бывает активный (поход, лыжи) и пассивный (музей, экскурсия)."]},"steps":{"head":"Как туризм связан с бизнесом (business), по шагам","items":["В крае есть красивое место","Туристы хотят его увидеть","Им нужны транспорт, гостиница, еда, экскурсовод","Люди открывают для этого бизнес","Туристы покупают сувениры на память"]},"scheme":"В центре — турист с чемоданом. Вокруг 4 картинки: «Место» (горы), «Где жить» (гостиница), «Что есть» (кафе), «Что купить» (сувенир).","examples":[{"lab":"Казахстан","text":"Бурабай — озёра и скалы; туристы живут в гостиницах, катаются на лодках, покупают сувениры. Лодка на час — 20 условных тенге, магнит — 5 условных тенге: всего 25 условных тенге. Туркестан — мавзолей Ходжи Ахмеда Ясави."},{"lab":"Мир","text":"В Египет едут смотреть пирамиды, там работают экскурсоводы и продают сувенирные пирамидки."}],"mistake":{"myth":"Дети думают, что туристы приезжают только «за границу», а в нашем крае смотреть нечего","fix":"Спросить, что показали бы гостю из другого города — у каждого края есть свои места."},"check":[{"q":"Кто такой турист?","a":"Гость, который приехал посмотреть новое место"},{"q":"Что можно купить туристу?","a":"Сувенир, экскурсию, еду"},{"q":"Катание на лыжах — активный или пассивный отдых?","a":"Активный"}],"kz":{"text":"Бурабай (Боровое) в Акмолинской области — известное курортное место Казахстана с озёрами, сосновым лесом и скалой Окжетпес.","link":"благодаря природе там работают гостиницы, лодочные станции, кафе и продавцы сувениров."},"world":{"text":"Египетские пирамиды каждый год привлекают миллионы туристов, и благодаря им работают гостиницы, кафе и гиды. Но много туристов — это и мусор, поэтому важно беречь памятники и природу.","link":""},"fact":"Мавзолей Ходжи Ахмеда Ясави в Туркестане стал первым объектом Казахстана в списке Всемирного наследия ЮНЕСКО в 2003 году; сюда приезжают туристы из многих стран.","cards":[{"n":"1","title":"Активный или пассивный?","lines":["Отдых: поход в горы, музей, катание на лыжах, экскурсия на автобусе, катание на лошади, отдых у озера.","Обведи зелёным активный отдых, синим — пассивный.","Ответы для тренера: активный — поход, лыжи, лошадь; пассивный — музей, экскурсия, отдых у озера."],"hand":"Сдать: карточку.","answers":[]},{"n":"2","title":"Буклет «Приглашаем в гости»","lines":["Страница 1: нарисуй первое место края и что там купить туристу.","Страница 2: нарисуй второе место и что там купить.","Скажи: «Приезжайте в …! Там можно … . Купите …»"],"hand":"Сдать: буклет пары.","answers":[]}],"homework":"Вместе с родителями найти фото одного интересного места нашего края и рассказать, что там может купить турист.","support":"Готовые картинки 4 мест края и 4 сувениров; ребёнок выбирает 2 места и соединяет с товаром.","advanced":"Придумать маршрут на 1 день для туриста: утро, обед, вечер — и что он будет покупать.","photo":{"src":"lessons/img/01_23.jpg","author":"GWANGJIN GO","q":["Что вы видите на фото? Как это связано с нашей темой?","Как туристу вести себя, чтобы место осталось красивым?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l23.pptx","name":"23. Туризм — чем наш край интересен гостям (1 кл).pptx","mb":1.6}},{"id":"01_24","g":1,"l":24,"topic":"Ярмарка: товар, вывеска и цена в тенге","module":"Страна бизнеса","format":"Симуляция, ярмарка","skills":["Командная работа","Финансовое мышление","Работа с клиентом"],"goal":"К концу урока ученик сможет подготовить свою часть ярмарки — товар, вывеску и цену в тенге — и продать товар, правильно посчитав деньги до 100.","criteria":["Я сделал свою часть: товар, вывеску или ценник.","Я назначил понятную цену в тенге и правильно считаю деньги.","Я вежливо продаю и покупаю."],"result":"Прилавок команды на ярмарке: товар (поделка или рисунок), вывеска с названием и ценник в условных тенге; итог продаж в тенге.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Праздничный рынок, где продают много разных товаров","shown":"Праздничный рынок, где продают много разных товаров","truth":true,"first":"Я"},{"term":"Цена (price)","real":"Сколько тенге стоит товар","shown":"Человек, который платит и получает товар","truth":false,"first":"Ц"},{"term":"Ценник","real":"Бумажка, на которой написана цена","shown":"Бумажка, на которой написана цена","truth":true,"first":"Ц"},{"term":"Вывеска","real":"Табличка с названием магазина или прилавка","shown":"Сколько тенге стоит товар","truth":false,"first":"В"},{"term":"Выручка","real":"Все деньги, которые продавец получил за день","shown":"Все деньги, которые продавец получил за день","truth":true,"first":"В"},{"term":"Покупатель","real":"Человек, который платит и получает товар","shown":"Табличка с названием магазина или прилавка","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Праздничный рынок, где продают много разных товаров"},{"term":"Цена (price)","def":"Сколько тенге стоит товар"},{"term":"Ценник","def":"Бумажка, на которой написана цена"},{"term":"Вывеска","def":"Табличка с названием магазина или прилавка"},{"term":"Выручка","def":"Все деньги, которые продавец получил за день"},{"term":"Покупатель","def":"Человек, который платит и получает товар"}],"english":"fair — ярмарка; price — цена","concepts":{"head":"Понятия","items":["Ярмарка (fair) — рынок на один день.","Цена (price) — сколько стоит товар.","Вывеска — название прилавка, чтобы покупатель нас заметил.","Ценник — где видна цена.","Выручка — все деньги за проданные товары."]},"steps":{"head":"Как подготовить прилавок, по шагам","items":["Команда выбирает товар (закладки, открытки, браслеты)","Каждый получает роль: мастер, художник вывески, продавец, кассир","Ставим цену: чем больше труда и материалов, тем дороже","Делаем вывеску — крупно, ярко, коротко","Продаём и считаем деньги"]},"scheme":"Рисунок прилавка: сверху вывеска «Название», на столе товары с ценниками «10 тенге», рядом кассир с коробкой. Под рисунком: «Продали 5 по 10 = 50 тенге».","examples":[{"lab":"Казахстан","text":"На ярмарке в Шымкенте мастер продаёт тюбетейки и сувениры с орнаментом, у каждого товара есть ценник. Наш"},{"lab":"Пример","text":"Команда сделала 6 закладок по 10 условных тенге и продала 5 — выручка 50 условных тенге."},{"lab":"Мир","text":"На рынках в Марокко мастера сами делают и продают ковры и посуду прямо у своего прилавка."}],"mistake":{"myth":"Ценник забыли или цена «100 рублей»","fix":"У нас только тенге и цена до 100; покупатель без ценника не знает, хватит ли денег, и уходит."},"check":[{"q":"Зачем нужна вывеска?","a":"Чтобы покупатель увидел и запомнил нас"},{"q":"Сколько получим за 3 открытки по 5 тенге?","a":"15 тенге"},{"q":"Кто считает деньги?","a":"Кассир"}],"kz":{"text":"Зелёный базар в Алматы — один из самых известных рынков Казахстана, где продают фрукты, сладости, специи и сувениры.","link":"у каждого прилавка есть товар, вывеска и цена, а продавцы зовут покупателей."},"world":{"text":"На рынках по всему миру, например в Марокко или Турции, мастера продают товары своими руками, и у прилавка обязательно есть цена или договорённость о ней. Честные цены помогают покупателям вернуться снова.","link":""},"fact":"Первые деньги на территории Казахстана чеканили ещё в средние века в городах на Великом Шёлковом пути, например в Отраре и Таразе, а там, где торговали караваны, проходили большие ярмарки.","cards":[{"n":"1","title":"Готовим прилавок","lines":["Роли: мастер (делает товар), художник (рисует вывеску), продавец (зовёт покупателей), кассир (считает деньги).","1) Товар: закладки, открытки или браслеты — 4–6 штук.","2) Вывеска: название прилавка крупными буквами.","3) Ценник: цена от 5 до 20 условных тенге."],"hand":"Сдать: готовый прилавок.","answers":[]},{"n":"2","title":"Подсчёт выручки","lines":["Мы сделали товаров: ____","Мы продали товаров: ____","Цена одного товара: ____ тенге","Выручка (все деньги): ____ тенге","Пример: 4 товара по 10 тенге = 10 + 10 + 10 + 10 = 40 тенге."],"hand":"Сдать: заполненную карточку.","answers":[]}],"homework":"Сохранить выручку команды (сумму) и нарисовать дома новую вывеску, которая привлечёт ещё больше покупателей.","support":"Шаблон ценника с готовыми цифрами 5, 10, 15, 20 и монеты-картинки для подсчёта; роль помощника кассира вместе с сильным учеником.","advanced":"Стать кассиром-контролёром: проверить подсчёт выручки двух команд и придумать акцию «2 товара за 15 тенге».","photo":{"src":"lessons/img/01_24.jpg","author":"Nguyễn Đức","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему покупатель вернётся к честному продавцу?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l24.pptx","name":"24. Ярмарка — товар, вывеска и цена в тенге (1 кл).pptx","mb":1.7}},{"id":"01_25","g":1,"l":25,"topic":"Покупатели товаров и услуг","module":"Страна бизнеса","format":"Комбинированный","skills":["Критическое мышление","Работа с клиентом"],"goal":"К концу урока ученик сможет объяснить, кто такой покупатель, и привести 2 примера покупок своей семьи: один товар и одну услугу.","criteria":["Я объясняю, кто такой покупатель.","Я отличаю товар от услуги.","Я привожу пример покупок своей семьи."],"result":"Плакат пары «Что покупает наша семья»: 2 товара и 2 услуги с рисунками.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Покупатель (customer)","real":"Человек, который платит деньги и получает товар или услугу","shown":"Человек, который платит деньги и получает товар или услугу","truth":true,"first":"П"},{"term":"Товар (product)","real":"Вещь, которую можно купить и потрогать: хлеб, книга, мяч","shown":"Насколько товар или услуга хорошие","truth":false,"first":"Т"},{"term":"Услуга","real":"Работа, которую человек делает для нас: стрижка, ремонт, урок","shown":"Работа, которую человек делает для нас: стрижка, ремонт, урок","truth":true,"first":"У"},{"term":"Потребитель","real":"Тот, кто пользуется товаром или услугой","shown":"Вещь, которую можно купить и потрогать: хлеб, книга, мяч","truth":false,"first":"П"},{"term":"Потребление","real":"Когда мы используем то, что купили","shown":"Когда мы используем то, что купили","truth":true,"first":"П"},{"term":"Качество","real":"Насколько товар или услуга хорошие","shown":"Тот, кто пользуется товаром или услугой","truth":false,"first":"К"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Покупатель (customer)","def":"Человек, который платит деньги и получает товар или услугу"},{"term":"Товар (product)","def":"Вещь, которую можно купить и потрогать: хлеб, книга, мяч"},{"term":"Услуга","def":"Работа, которую человек делает для нас: стрижка, ремонт, урок"},{"term":"Потребитель","def":"Тот, кто пользуется товаром или услугой"},{"term":"Потребление","def":"Когда мы используем то, что купили"},{"term":"Качество","def":"Насколько товар или услуга хорошие"}],"english":"customer — покупатель; product — товар","concepts":{"head":"Понятия","items":["Покупатель (customer) — тот, кто платит.","Потребитель — тот, кто пользуется (папа купил сок, а пьёт его ребёнок — ребёнок потребитель).","Товар (product) — вещь.","Услуга — помощь или работа.","Качество — насколько хорошо."]},"steps":{"head":"Как это работает","items":["У человека есть потребность (хочет есть)","Он идёт к продавцу","Выбирает товар или услугу","Платит","Пользуется и думает, хорошее ли качество. Если качество хорошее — придёт снова"]},"scheme":"Человечек «Покупатель» в центре. Слева корзинка «Товары» (хлеб, книга, мяч), справа ножницы «Услуги» (стрижка, врач, такси). Внизу звёздочки «Качество».","examples":[{"lab":"Казахстан","text":"Мама купила в магазине хлеб за 5 условных тенге и молоко за 10 условных тенге — это товары, всего 15 условных тенге. Потом папа отвёз машину на мойку за 20 условных тенге — это услуга."},{"lab":"Мир","text":"В Японии в автоматах можно купить напиток без продавца: покупатель сам выбирает и платит."}],"mistake":{"myth":"Дети считают, что покупатели — только взрослые","fix":"Спросить «Ты покупал что-то в школьном буфете? Значит, ты тоже покупатель»."},"check":[{"q":"Стрижка — товар или услуга?","a":"Услуга"},{"q":"Кто покупатель, если бабушка покупает внуку мороженое?","a":"Бабушка; внук — потребитель"},{"q":"Почему покупатель возвращается в магазин?","a":"Хорошее качество и вежливый продавец"}],"kz":{"text":"Сеть магазинов Magnum — одна из крупнейших сетей супермаркетов Казахстана.","link":"каждый день туда приходят тысячи покупателей за товарами, а магазин старается, чтобы им было удобно: тележки, кассы, понятные ценники."},"world":{"text":"Во многих странах есть правила защиты покупателей: товар должен быть качественным, а если он сломался, его можно вернуть. Это помогает людям доверять магазинам по всему миру.","link":""},"fact":"Первую тележку для супермаркета придумал в 1937 году американский владелец магазинов Сильван Голдман, чтобы покупатели могли купить больше, чем помещается в руках.","cards":[{"n":"1","title":"Товар или услуга?","lines":["Картинки: хлеб, стрижка, мяч, такси, книга, урок плавания, молоко, ремонт обуви.","Разложи в два столбика: «Товар (product)» и «Услуга».","Ответы для тренера: товары — хлеб, мяч, книга, молоко; услуги — стрижка, такси, урок плавания, ремонт обуви."],"hand":"Сдать: карточку.","answers":[]},{"n":"2","title":"Что покупает наша семья","lines":["Нарисуйте 2 товара и 2 услуги, которые покупает ваша семья.","Скажите: «Мы покупатели (customers). Мы покупаем … и …»."],"hand":"Сдать: плакат пары.","answers":[]}],"homework":"Пойти с родителями в магазин и назвать 1 товар и 1 услугу, которые увидишь (например, хлеб и упаковка подарка).","support":"Картинки товаров и услуг с подсказкой: «Можно потрогать и унести — товар; кто-то делает для тебя работу — услуга».","advanced":"Придумать, как продавец может сделать качество услуги лучше, чтобы покупатель вернулся, и назвать 2 идеи.","photo":{"src":"lessons/img/01_25.jpg","author":"Simon Kadula","q":["Что вы видите на фото? Как это связано с нашей темой?","Что ты сделаешь, если купленная игрушка сразу сломалась?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l25.pptx","name":"25. Покупатели товаров и услуг (1 кл).pptx","mb":1.4}},{"id":"01_26","g":1,"l":26,"topic":"Умный покупатель: нужное и желаемое","module":"Страна бизнеса","format":"Комбинированный","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет разделить 6 покупок на нужные и желаемые и объяснить свой выбор, посчитав покупки в пределах 50 тенге.","criteria":["Я отличаю нужную покупку от желаемой.","Я объясняю, почему выбрал именно так.","Я считаю, хватает ли денег на покупки."],"result":"Корзина умного покупателя: выбор покупок на 50 условных тенге, где сначала нужное, потом желаемое, с подсчётом суммы.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Потребности (needs)","real":"То, без чего трудно жить: еда, одежда, дом, лекарства","shown":"То, без чего трудно жить: еда, одежда, дом, лекарства","truth":true,"first":"П"},{"term":"Нужная покупка","real":"То, что необходимо сейчас","shown":"Сколько денег у нас есть на покупки","truth":false,"first":"Н"},{"term":"Желаемая покупка","real":"То, что хочется, но можно подождать","shown":"То, что хочется, но можно подождать","truth":true,"first":"Ж"},{"term":"Покупатель (customer)","real":"Человек, который платит и получает товар","shown":"То, что необходимо сейчас","truth":false,"first":"П"},{"term":"Качество","real":"Насколько хорош товар","shown":"Насколько хорош товар","truth":true,"first":"К"},{"term":"Бюджет","real":"Сколько денег у нас есть на покупки","shown":"Человек, который платит и получает товар","truth":false,"first":"Б"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Потребности (needs)","def":"То, без чего трудно жить: еда, одежда, дом, лекарства"},{"term":"Нужная покупка","def":"То, что необходимо сейчас"},{"term":"Желаемая покупка","def":"То, что хочется, но можно подождать"},{"term":"Покупатель (customer)","def":"Человек, который платит и получает товар"},{"term":"Качество","def":"Насколько хорош товар"},{"term":"Бюджет","def":"Сколько денег у нас есть на покупки"}],"english":"customer — покупатель; needs — потребности","concepts":{"head":"Понятия","items":["Потребности (needs) — то, без чего нельзя: еда, вода, одежда, тетради для школы.","Нужное — покупаем в первую очередь.","Желаемое — игрушки, сладости, можно подождать.","Умный покупатель (customer) сначала покупает нужное."]},"steps":{"head":"Как выбирать, по шагам","items":["Посчитать, сколько денег есть","Составить список","Отметить, что нужно, а что хочется","Купить нужное","Если деньги остались — купить одно желаемое","Проверить качество товара"]},"scheme":"Весы: на левой чаше «Нужное» (хлеб, тетрадь, шапка зимой), на правой «Желаемое» (игрушка, сладости). Над весами кошелёк «50 тенге». Стрелка «Сначала нужное → потом желаемое».","examples":[{"lab":"Казахстан","text":"У Айгерим 50 условных тенге. Нужное: хлеб — 10, молоко — 15. Это 25 тенге. Осталось 50 − 25 = 25 тенге. Желаемое: шоколадка за 10 тенге — хватает, остаётся 15 тенге."},{"lab":"Мир","text":"В разных странах дети собирают деньги в копилку, чтобы купить желаемую вещь позже."}],"mistake":{"myth":"«Всё, что я хочу, — нужное»","fix":"Задать вопрос «Что будет, если не купить сегодня?» — если ничего плохого, это желаемое."},"check":[{"q":"Зимняя шапка в мороз — нужное или желаемое?","a":"Нужное"},{"q":"Что купить первым — хлеб или игрушку?","a":"Хлеб"},{"q":"Хватит ли 30 тенге на тетрадь за 10 и мяч за 25?","a":"Нет: 35 больше 30"}],"kz":{"text":"Национальный банк Казахстана проводит для детей и школьников занятия и конкурсы по финансовой грамотности.","link":"там учат, как планировать покупки и копить."},"world":{"text":"Во многих странах учат «осознанному потреблению» — покупать то, что действительно нужно, чтобы меньше выбрасывать вещей; это цель ООН № 12 «Ответственное потребление».","link":""},"fact":"Копилки в форме свиньи известны в Европе уже несколько сотен лет; одна из версий связывает их с глиной «pygg», из которой делали сосуды для монет.","cards":[{"n":"1","title":"Нужное или желаемое?","lines":["Покупки: хлеб, игрушечная машинка, тетрадь, конфеты, тёплая шапка зимой, наклейки.","Раздели на «Нужное (needs)» и «Желаемое».","Ответы для тренера: нужное — хлеб, тетрадь, тёплая шапка; желаемое — машинка, конфеты, наклейки."],"hand":"Сдать: карточку.","answers":[]},{"n":"2","title":"Корзина умного покупателя","lines":["У вас 50 условных тенге.","Цены: хлеб — 10, молоко — 15, тетрадь — 10, конфеты — 10, машинка — 30, наклейки — 5.","1) Сначала выберите нужное и сложите цены.","2) Сколько осталось? 50 − ___ = ___","3) Можно ли купить одно желаемое?","Пример ответа: хлеб + молоко + тетрадь = 35; осталось 15; можно купить конфеты (10), останется 5."],"hand":"Сдать: корзину с подсчётом.","answers":[]}],"homework":"Составить с родителями список покупок на выходные и отметить в нём 3 нужные и 1 желаемую покупку.","support":"Картинки с подписями «нужно» / «хочу» на обороте для самопроверки и числовая линейка до 50.","advanced":"Собрать корзину на 50 тенге так, чтобы осталось ровно 5 тенге в копилку, и объяснить выбор.","photo":{"src":"lessons/img/01_26.jpg","author":"Jack Lee","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие вещи ты купил и почти не пользовался?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l26.pptx","name":"26. Умный покупатель — нужное и желаемое (1 кл).pptx","mb":1.6}},{"id":"01_27","g":1,"l":27,"topic":"После ярмарки: считаем выручку","module":"Страна бизнеса","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Критическое мышление","Командная работа"],"goal":"К концу урока ученик сможет посчитать выручку своей команды после ярмарки в пределах 100 тенге и назвать одну причину, почему товар покупали или не покупали.","criteria":["Я правильно считаю выручку команды.","Я называю, какой товар продавался лучше и почему.","Я предлагаю, что улучшить в следующий раз."],"result":"Таблица итогов ярмарки команды: сколько товаров продано, выручка в тенге и один вывод «В следующий раз мы …», проверенный на мини-ярмарке.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Выручка (revenue)","real":"Все деньги, которые продавец получил за проданный товар","shown":"Все деньги, которые продавец получил за проданный товар","truth":true,"first":"В"},{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"То, что мы поняли и сделаем лучше","truth":false,"first":"Я"},{"term":"Цена","real":"Сколько тенге стоит один товар","shown":"Сколько тенге стоит один товар","truth":true,"first":"Ц"},{"term":"Итог","real":"Что получилось в конце работы","shown":"Праздничный рынок на один день","truth":false,"first":"И"},{"term":"Остаток","real":"Товар, который не продали","shown":"Товар, который не продали","truth":true,"first":"О"},{"term":"Вывод","real":"То, что мы поняли и сделаем лучше","shown":"Что получилось в конце работы","truth":false,"first":"В"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Выручка (revenue)","def":"Все деньги, которые продавец получил за проданный товар"},{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Цена","def":"Сколько тенге стоит один товар"},{"term":"Итог","def":"Что получилось в конце работы"},{"term":"Остаток","def":"Товар, который не продали"},{"term":"Вывод","def":"То, что мы поняли и сделаем лучше"}],"english":"fair — ярмарка; revenue — выручка","concepts":{"head":"Понятия","items":["Выручка (revenue) — все деньги за проданный товар.","Остаток — что не продали.","Итог — что получилось.","Вывод — что сделаем иначе."]},"steps":{"head":"Как посчитать выручку, по шагам","items":["Посчитать, сколько товаров было","Посчитать, сколько осталось","Было минус осталось — столько продали","Сложить цену каждого проданного товара","Проверить, совпадает ли с деньгами в кассе"]},"scheme":"Таблица: «Было — Осталось — Продали — Цена — Выручка». Строка-пример: 8 — 2 — 6 — 5 — 30 тенге.","examples":[{"lab":"Казахстан","text":"Команда «Алма» сделала 8 открыток по 5 условных тенге. Осталось 2. Продали 8 − 2 = 6. Выручка: 5 + 5 + 5 + 5 + 5 + 5 = 30 тенге. Команда «Тулпар» продала 4 браслета по 10 тенге — 40 тенге. Значит, у «Тулпара» выручка больше, хотя товаров продали меньше."},{"lab":"Мир","text":"На фермерских рынках во Франции продавцы вечером тоже считают кассу и решают, что привезти завтра."}],"mistake":{"myth":"Дети считают выручкой все деньги, которые были у покупателей, или число товаров","fix":"Показать: выручка — только деньги в нашей кассе, а «6 открыток» — это не «6 тенге»."},"check":[{"q":"Что такое выручка?","a":"Все деньги за проданный товар"},{"q":"Было 10, осталось 3 — сколько продали?","a":"7"},{"q":"Продали 3 товара по 10 тенге — какая выручка?","a":"30 тенге"}],"kz":{"text":"Кондитерская фабрика «Рахат» (Алматы) — известный казахстанский производитель конфет и шоколада.","link":"любой бизнес считает, сколько продал, и решает, что делать больше, а что меньше."},"world":{"text":"Маленькие фермеры по всему миру, например на рынках Франции и Италии, каждый вечер считают выручку и остаток, чтобы не привозить лишнего и не выбрасывать продукты. Это помогает беречь еду.","link":""},"fact":"Кассовый аппарат изобрёл в 1879 году американский владелец салуна Джеймс Ритти, чтобы точно считать выручку и не терять деньги.","cards":[{"n":"1","title":"Что было и что осталось","lines":["Сколько товаров мы сделали? ____","Сколько осталось? ____","Сколько продали? ____ − ____ = ____"],"hand":"Сдать: карточку.","answers":[]},{"n":"2","title":"Наша выручка (revenue)","lines":["Цена одного товара: ____ тенге.","Продали: ____ штук.","Выручка: сложи цену столько раз, сколько продали: ____ тенге.","Пример: 6 открыток по 5 тенге = 30 тенге.","Задача: команда продала 4 браслета по 10 тенге и 2 закладки по 5 тенге. Какая выручка?","Вывод: «В следующий раз мы …»"],"hand":"Сдать: заполненную таблицу.","answers":[["","50 тенге."]]}],"homework":"Рассказать родителям, какую выручку получила команда, и спросить, как они считают деньги в семье при покупках.","support":"Таблица с уже вписанными ценами и монеты-картинки; подсчёт выручки «по одной монете» вместе с тренером.","advanced":"Посчитать, какой была бы выручка, если бы продали весь товар, и сколько тенге команда «не получила».","photo":{"src":"lessons/img/01_27.jpg","author":"Alexander Mils","q":["Что вы видите на фото? Как это связано с нашей темой?","Что делать с товаром, который не продали?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l27.pptx","name":"27. После ярмарки — считаем выручку (1 кл).pptx","mb":1.5}},{"id":"01_28","g":1,"l":28,"topic":"Визитка нашего бизнес-города","module":"Страна бизнеса","format":"Комбинированный","skills":["Креативность","Презентация","Командная работа"],"goal":"К концу урока ученик сможет нарисовать визитку своего бизнес-города для чашки или футболки: название, символ и чем город знаменит.","criteria":["Я придумал название и символ своего города.","Я показал на визитке, чем знаменит город.","Я рассказал о визитке другу и узнал о его городе."],"result":"Эскиз визитки бизнес-города на шаблоне чашки или футболки: название, символ, 1 фраза «Наш город знаменит …».","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Визитка","real":"Маленькая картинка или карточка, которая рассказывает, кто ты и чем занимаешься","shown":"Маленькая картинка или карточка, которая рассказывает, кто ты и чем занимаешься","truth":true,"first":"В"},{"term":"Символ","real":"Рисунок, по которому сразу узнают город или фирму","shown":"Подарок на память, например чашка с рисунком города","truth":false,"first":"С"},{"term":"Нетворкинг","real":"Знакомство с людьми, чтобы потом вместе делать дела","shown":"Знакомство с людьми, чтобы потом вместе делать дела","truth":true,"first":"Н"},{"term":"Город (city)","real":"Место, где живёт много людей и работает бизнес","shown":"Рисунок, по которому сразу узнают город или фирму","truth":false,"first":"Г"},{"term":"Бизнес (business)","real":"Дело, которое делает товары или услуги","shown":"Дело, которое делает товары или услуги","truth":true,"first":"Б"},{"term":"Сувенир","real":"Подарок на память, например чашка с рисунком города","shown":"Место, где живёт много людей и работает бизнес","truth":false,"first":"С"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Визитка","def":"Маленькая картинка или карточка, которая рассказывает, кто ты и чем занимаешься"},{"term":"Символ","def":"Рисунок, по которому сразу узнают город или фирму"},{"term":"Нетворкинг","def":"Знакомство с людьми, чтобы потом вместе делать дела"},{"term":"Город (city)","def":"Место, где живёт много людей и работает бизнес"},{"term":"Бизнес (business)","def":"Дело, которое делает товары или услуги"},{"term":"Сувенир","def":"Подарок на память, например чашка с рисунком города"}],"english":"business — бизнес; city — город","concepts":{"head":"Понятия","items":["Визитка — «лицо» города или человека: название, символ, чем знаменит.","Символ — простой рисунок, который легко запомнить.","Нетворкинг — знакомство и обмен визитками, чтобы потом дружить и работать вместе."]},"steps":{"head":"Как сделать визитку, по шагам","items":["Вспомнить свой бизнес-город (city): что в нём делают и продают","Придумать короткое название","Выбрать один символ (яблоко, завод, юрта, солнце)","Написать короткую фразу","Нарисовать ярко и крупно, чтобы было видно на чашке или футболке"]},"scheme":"Контур чашки. На ней: сверху — название города, в центре — символ, снизу — фраза «знаменит …». Рядом контур футболки с тем же макетом.","examples":[{"lab":"Казахстан","text":"Символ Астаны — Байтерек, его рисуют на магнитах, чашках, футболках; символ Алматы — горы и яблоко. Магазин сувениров продаёт чашку с Байтереком за 30 условных тенге и магнит за 10 условных тенге."},{"lab":"Мир","text":"Символ Нью-Йорка — надпись с сердечком, её печатают на миллионах футболок."}],"mistake":{"myth":"Дети рисуют очень много мелких деталей, и визитку не понять","fix":"Показать визитку с 10 деталями и с 1 символом — какая видна издалека?"},"check":[{"q":"Зачем городу символ?","a":"Чтобы его узнавали и запоминали"},{"q":"Что должно быть на визитке?","a":"Название, символ, чем знаменит"},{"q":"Что такое нетворкинг?","a":"Знакомство, чтобы потом вместе делать дела"}],"kz":{"text":"Байтерек в Астане — символ столицы Казахстана. Его изображение есть на сувенирах, открытках и логотипах, а сам монумент посещают тысячи туристов.","link":"хороший символ становится визиткой города и помогает продавать сувениры."},"world":{"text":"Многие города мира узнают по символу: Париж — по Эйфелевой башне, Нью-Йорк — по надписи с сердечком. Такие символы печатают на сувенирах, и туристы увозят их домой по всему миру.","link":""},"fact":"Знаменитый логотип «I ♥ NY» нарисовал дизайнер Милтон Глейзер в 1977 году для рекламы штата Нью-Йорк; теперь его печатают на футболках и чашках по всему миру.","cards":[{"n":"1","title":"Визитка нашего бизнес-города","lines":["1) Название города: ________","2) Символ (один рисунок): ________","3) Чем знаменит: «Наш город (city) знаменит …»","Нарисуй всё на шаблоне чашки или футболки: название сверху, символ в центре, фраза снизу."],"hand":"Сдать: эскиз.","answers":[]},{"n":"2","title":"Ярмарка знакомств","lines":["Подойди к 2 одноклассникам. Скажи: «Здравствуй! Я из города … . Он знаменит … .»","Узнай: из какого он города? Чем город может помочь твоему?"],"hand":"Сдать: имя одного «партнёра» и его город (тренер записывает устно).","answers":[]}],"homework":"Показать визитку семье и спросить, понятно ли, чем знаменит город; дорисовать, если нужно.","support":"Готовые символы для вырезания и приклеивания (яблоко, юрта, завод, солнце) и шаблон фразы.","advanced":"Нарисовать вторую визитку — для магнита, и придумать короткий девиз города из 3–4 слов.","photo":{"src":"lessons/img/01_28.jpg","author":"Dex Ezekiel","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой символ нашего города узнали бы иностранцы?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l28.pptx","name":"28. Визитка нашего бизнес-города (1 кл).pptx","mb":1.5}},{"id":"01_29","g":1,"l":29,"topic":"Презентация бизнес-городов","module":"Страна бизнеса","format":"Питч и защита","skills":["Презентация","Командная работа"],"goal":"К концу урока команда сможет за 2 минуты представить свой бизнес-город: название, что в нём делают и продают, — а ученик сможет задать вопрос другой команде.","criteria":["Я говорю громко и понятно свою часть выступления.","Я называю, что в нашем городе делают и продают.","Я внимательно слушаю других и задаю вопрос."],"result":"Двухминутное выступление команды с плакатом бизнес-города и голосование класса за лучшие города.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Питчи","min":20},{"stage":"Голосование","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Презентация (presentation)","real":"Короткий рассказ о своей работе перед слушателями","shown":"Короткий рассказ о своей работе перед слушателями","truth":true,"first":"П"},{"term":"Бизнес-город","real":"Придуманный город, где люди делают и продают товары и услуги","shown":"Выбор лучшего, когда каждый отдаёт свой голос","truth":false,"first":"Б"},{"term":"Выступающий","real":"Человек, который рассказывает","shown":"Человек, который рассказывает","truth":true,"first":"В"},{"term":"Слушатель","real":"Тот, кто внимательно слушает и задаёт вопросы","shown":"Придуманный город, где люди делают и продают товары и услуги","truth":false,"first":"С"}],"perm":[1,0,3,2]},"glossary":[{"term":"Презентация (presentation)","def":"Короткий рассказ о своей работе перед слушателями"},{"term":"Бизнес-город","def":"Придуманный город, где люди делают и продают товары и услуги"},{"term":"Выступающий","def":"Человек, который рассказывает"},{"term":"Слушатель","def":"Тот, кто внимательно слушает и задаёт вопросы"},{"term":"Голосование","def":"Выбор лучшего, когда каждый отдаёт свой голос"}],"english":"business — бизнес; presentation — презентация","concepts":{"head":"Понятия","items":["Презентация (presentation) — короткий рассказ о работе.","Бизнес-город — наш придуманный город с бизнесом (business).","Выступающий говорит, слушатели слушают и задают вопросы."]},"steps":{"head":"Как выступить за 2 минуты, по шагам","items":["Поздороваться и назвать город","Показать символ на плакате","Сказать, что в городе делают (завод, ферма, кафе)","Сказать, что продают и кому","Пригласить в гости","Поблагодарить и ответить на вопрос. Каждый в команде говорит свой шаг"]},"scheme":"Пять ступенек: «Привет» → «Название и символ» → «Что делаем» → «Что продаём» → «Приглашаем! Спасибо!» Рядом песочные часы «2 минуты».","examples":[{"lab":"Казахстан","text":"«Наш город — Алтын Алма. Символ — золотое яблоко. Здесь выращивают яблоки и делают сок. Бутылка сока стоит 10 условных тенге. Приезжайте!» Ярмарка ЭКСПО-2017 в Астане: каждая страна показывала свой павильон и рассказывала о себе гостям — это тоже презентация."},{"lab":"Мир","text":"На выставках в разных странах компании за пару минут рассказывают о своём товаре."}],"mistake":{"myth":"Говорит один ученик, остальные стоят молча, или все говорят одновременно","fix":"Заранее разделить шаги, каждый держит в руке номер своей ступеньки."},"check":[{"q":"С чего начинают выступление?","a":"Здороваются и называют город"},{"q":"Чем заканчивают?","a":"Благодарят"},{"q":"Что делает слушатель?","a":"Слушает и задаёт вопрос"}],"kz":{"text":"Международная выставка ЭКСПО-2017 в Астане. В ней участвовали более ста стран, а здание-сфера «Нұр Әлем» стало новым символом столицы.","link":"каждая страна за короткое время презентовала себя посетителям."},"world":{"text":"На всемирной выставке ЭКСПО страны мира показывают свои достижения в павильонах и рассказывают о себе гостям. В 2017 году такая выставка проходила в Астане на тему «Энергия будущего».","link":""},"fact":"Здание-шар «Нұр Әлем», построенное к ЭКСПО-2017 в Астане, — одно из самых больших сферических зданий в мире, в нём работает музей энергии будущего.","cards":[{"n":"1","title":"План выступления (2 минуты)","lines":["Ступенька 1: «Здравствуйте! Наш город называется …»","Ступенька 2: «Наш символ — …»","Ступенька 3: «В нашем городе делают …»","Ступенька 4: «Мы продаём … за … тенге.»","Ступенька 5: «Приезжайте к нам в гости! Спасибо!»","Запишите имя того, кто говорит каждую ступеньку."],"hand":"Сдать: план с именами.","answers":[]},{"n":"2","title":"Вопросы слушателя","lines":["Выбери один вопрос для команды:","— Почему вы выбрали такой символ?","— Кто покупает ваш товар?","— Что самое интересное в вашем городе?","— Сколько стоит ваш товар?"],"hand":"Сдать: устно задать вопрос.","answers":[]}],"homework":"Рассказать дома о своём бизнес-городе за 2 минуты, как на уроке, и спросить у семьи один вопрос-совет.","support":"Карточка-подсказка с началом фразы для своей ступеньки и возможность выступать рядом с другом.","advanced":"Подготовить «рекламный вопрос» для каждой команды и выступить ведущим голосования.","photo":{"src":"lessons/img/01_29.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Что ваш бизнес-город показал бы гостям со всего мира?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l29.pptx","name":"29. Презентация бизнес-городов (1 кл).pptx","mb":1.6}},{"id":"01_30","g":1,"l":30,"topic":"Игра-повторение «Путешествие по стране бизнеса","module":"Страна бизнеса","format":"Деловая игра","skills":["Командная работа","Критическое мышление"],"goal":"К концу урока ученик сможет в игре по станциям назвать и объяснить 5 тем полугодия — бизнес, деньги, промышленность, услуги, магазин — приводя по одному примеру к каждой.","criteria":["Я называю пример к каждой станции: бизнес, деньги, промышленность, услуги, магазин.","Я помогаю команде и жду своей очереди.","Я правильно считаю баллы команды."],"result":"Маршрутный лист команды «Путешествие по стране бизнеса» с отметками 5 станций и набранными баллами.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Бизнес (business)","real":"Дело, которое делает товары или услуги для людей и приносит доход","shown":"Дело, которое делает товары или услуги для людей и приносит доход","truth":true,"first":"Б"},{"term":"Деньги","real":"То, чем платят за товары и услуги; в Казахстане — тенге","shown":"Занятие по правилам, где можно выиграть","truth":false,"first":"Д"},{"term":"Промышленность","real":"Заводы и фабрики, где делают товары","shown":"Заводы и фабрики, где делают товары","truth":true,"first":"П"},{"term":"Услуга","real":"Работа, которую человек делает для других","shown":"То, чем платят за товары и услуги; в Казахстане — тенге","truth":false,"first":"У"},{"term":"Магазин","real":"Место, где продают товары","shown":"Место, где продают товары","truth":true,"first":"М"},{"term":"Игра (game)","real":"Занятие по правилам, где можно выиграть","shown":"Работа, которую человек делает для других","truth":false,"first":"И"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бизнес (business)","def":"Дело, которое делает товары или услуги для людей и приносит доход"},{"term":"Деньги","def":"То, чем платят за товары и услуги; в Казахстане — тенге"},{"term":"Промышленность","def":"Заводы и фабрики, где делают товары"},{"term":"Услуга","def":"Работа, которую человек делает для других"},{"term":"Магазин","def":"Место, где продают товары"},{"term":"Игра (game)","def":"Занятие по правилам, где можно выиграть"}],"english":"business — бизнес; game — игра","concepts":{"head":"Главное о теме","items":["Бизнес (business) — дело, которое делает товары или услуги и приносит доход.","Деньги — то, чем платят; в Казахстане — тенге.","Промышленность — заводы и фабрики.","Услуги — работа для людей: врач, парикмахер, таксист.","Магазин — место, где товар встречается с покупателем."]},"steps":{"head":"Как всё связано, по шагам","items":["В стране есть ресурсы (зерно, нефть, уголь)","На заводах из них делают товары","Товары везут в магазин","Покупатель платит деньгами","Люди оказывают услуги друг другу","Так работает страна бизнеса"]},"scheme":"Карта-маршрут из 5 кружков-станций: «Бизнес» → «Деньги» → «Промышленность» → «Услуги» → «Магазин». От станции к станции — стрелки, на финише — флажок.","examples":[{"lab":"Казахстан","text":"Из казахстанской пшеницы мельница делает муку, пекарня печёт хлеб, магазин продаёт буханку за 10 условных тенге; если продали 5 буханок — выручка 50 условных тенге."},{"lab":"Мир","text":"В Швейцарии из какао и молока на фабриках делают шоколад и продают его по всему миру."}],"mistake":{"myth":"Дети путают товар и услугу (называют стрижку товаром)","fix":"Правило «Можно унести в руках — товар; кто-то делает работу для тебя — услуга»."},"check":[{"q":"Чем платят в Казахстане?","a":"Тенге"},{"q":"Пекарня — это промышленность или услуга?","a":"Производство: делает товар — хлеб"},{"q":"Где товар встречается с покупателем?","a":"В магазине"}],"kz":{"text":"Хлеб из казахстанской пшеницы. Казахстан — один из крупных производителей пшеницы и муки, которые продают и в другие страны.","link":"на примере хлеба видно все станции — ресурс, промышленность, магазин, деньги."},"world":{"text":"Шоколад, который продают по всему миру, делают из какао-бобов, которые выращивают в Африке, например в Кот-д'Ивуаре и Гане, а фабрики работают в Европе. Так страны мира связаны цепочкой бизнеса.","link":""},"fact":"Казахстан входит в число крупнейших экспортёров пшеничной муки в мире; казахстанскую муку покупают соседние страны Центральной Азии и Афганистан.","cards":[{"n":"1","title":"Маршрутный лист команды","lines":["Команда: ________","Станция 1 «Бизнес» — баллы: __","Станция 2 «Деньги» — баллы: __","Станция 3 «Промышленность» — баллы: __","Станция 4 «Услуги» — баллы: __","Станция 5 «Магазин» — баллы: __","Итого: __ (сложите все баллы)."],"hand":"Сдать: маршрутный лист.","answers":[]},{"n":"2","title":"Задания станций","lines":["«Бизнес»: назовите 2 бизнеса нашего города.","«Деньги»: сложите монеты 10 + 10 + 5 + 5.","«Промышленность»: разложите по порядку картинки «зерно — мука — хлеб».","«Услуги»: выберите из 6 картинок 3 услуги (стрижка, такси, врач).","«Магазин»: купите хлеб за 10 тенге и сок за 15 тенге. Сколько заплатите?"],"hand":"Сдать: ответы на станциях.","answers":[["","30 тенге."],["","25 тенге."]]}],"homework":"Рассказать родителям про 5 станций и найти дома по одному примеру к каждой (товар, услуга, деньги…).","support":"Картинки-подсказки на каждой станции и роль «счётчика баллов» вместе с тренером.","advanced":"Придумать свою, шестую станцию (например, «Банк» или «Туризм») и задание для неё.","photo":{"src":"lessons/img/01_30.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Из какой страны может приехать то, что ты ел сегодня на завтрак?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l30.pptx","name":"30. Игра-повторение «Путешествие по стране бизнеса» (1 кл).pptx","mb":1.5}},{"id":"01_31","g":1,"l":31,"topic":"Резерв: повторение, проект или блиц-игра","module":"Страна бизнеса","format":"Деловая игра","skills":["Командная работа","Критическое мышление"],"goal":"К концу урока ученик сможет в блиц-игре «Бизнес-лото» правильно отнести 8 картинок к темам модуля (город, кафе, традиции, туризм, покупатель) и объяснить 2 из них.","criteria":["Я правильно кладу картинки на свои поля.","Я объясняю, почему картинка относится к этой теме.","Я играю честно и считаю баллы."],"result":"Заполненная карточка «Бизнес-лото» команды и устное объяснение двух ответов.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Проект (project)","real":"Большое дело, которое делают по плану и показывают результат","shown":"Большое дело, которое делают по плану и показывают результат","truth":true,"first":"П"},{"term":"Игра (game)","real":"Занятие по правилам","shown":"Человек, который платит и получает товар или услугу","truth":false,"first":"И"},{"term":"Город","real":"Место, где живут люди и работает бизнес","shown":"Место, где живут люди и работает бизнес","truth":true,"first":"Г"},{"term":"Кафе","real":"Место, где готовят еду для гостей","shown":"Занятие по правилам","truth":false,"first":"К"},{"term":"Турист","real":"Человек, который приехал посмотреть новое место","shown":"Человек, который приехал посмотреть новое место","truth":true,"first":"Т"},{"term":"Покупатель","real":"Человек, который платит и получает товар или услугу","shown":"Место, где готовят еду для гостей","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Проект (project)","def":"Большое дело, которое делают по плану и показывают результат"},{"term":"Игра (game)","def":"Занятие по правилам"},{"term":"Город","def":"Место, где живут люди и работает бизнес"},{"term":"Кафе","def":"Место, где готовят еду для гостей"},{"term":"Турист","def":"Человек, который приехал посмотреть новое место"},{"term":"Покупатель","def":"Человек, который платит и получает товар или услугу"}],"english":"project — проект; game — игра","scheme":"Поле лото 5 столбцов: «Город | Кафе | Традиции | Туризм | Покупатель». Под каждым — пустые клетки для картинок.","examples":[{"lab":"Казахстан","text":"Картинка «бешбармак» — тема «Кафе»; «Байтерек» — «Город»; «Бурабай» — «Туризм»; «тұсау кесу» — «Традиции»; «мама покупает хлеб за 10 тенге» — «Покупатель». Если команда дала 6 верных ответов по 2 балла, у неё 12 баллов."},{"lab":"Мир","text":"«Эйфелева башня» — тема «Туризм»."}],"mistake":{"myth":"Команда кладёт картинку наугад","fix":"Правило «без “потому что” балл не засчитывается»."},"check":[{"q":"Куда положить «меню»?","a":"Кафе"},{"q":"Куда «сувенир-магнит»?","a":"Туризм"},{"q":"Куда «Наурыз»?","a":"Традиции"}],"kz":{"text":"Национальные игры Казахстана, например асық ату, — традиционная игра с косточками, в которую играли дети кочевников.","link":"игра учит правилам, честности и командному духу, как и наше лото."},"world":{"text":"В разных странах дети играют в лото и настольные игры, чтобы учиться: например, в Германии и Японии популярны развивающие игры про магазины и города.","link":""},"fact":"Игра лото известна в Европе уже несколько сотен лет; её корни связывают с итальянской лотереей XVI века, а в XIX веке лото стали использовать как обучающую игру для детей.","cards":[{"n":"1","title":"Поле «Бизнес-лото»","lines":["Столбцы: Город | Кафе | Традиции | Туризм | Покупатель.","Правило: кладёшь фишку — объясняешь «потому что». Верно — 2 балла."],"hand":"Сдать: заполненное поле.","answers":[]},{"n":"2","title":"Картинки для тренера","lines":["Раунд 1: Байтерек (Город), меню (Кафе), Наурыз (Традиции), Бурабай (Туризм), мама с корзиной (Покупатель), официант (Кафе), сувенир-магнит (Туризм), дастархан (Традиции).","Раунд 2: назовите 3 примера к теме «Город», «Кафе», «Туризм».","Задача для подсчёта: 6 верных ответов по 2 балла = 12 баллов."],"hand":"Сдать: таблицу баллов.","answers":[]}],"homework":"Сыграть дома в «Бизнес-лото» с семьёй: назвать по одному примеру к каждой из 5 тем.","support":"Поле с маленькими картинками-подсказками в углу каждой темы; работа в паре с сильным учеником.","advanced":"Нарисовать 2 новые картинки для лото и проверить, угадают ли тему другие команды.","photo":{"src":"lessons/img/01_31.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую картинку из другой страны мы добавили бы в наше лото?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l31.pptx","name":"31. Резерв — повторение, проект или блиц-игра (1 кл).pptx","mb":1.4}},{"id":"01_32","g":1,"l":32,"topic":"Резерв: повторение, проект или блиц-игра","module":"Страна бизнеса","format":"Деловая игра","skills":["Командная работа","Креативность"],"goal":"К концу урока ученик сможет вместе с командой довести проект «Карта страны бизнеса» и в игре-эстафете назвать 3 бизнеса своего города и что они продают.","criteria":["Я добавил на карту свой бизнес с товаром и ценой.","Я называю 3 бизнеса своего бизнес-города.","Я выполняю свою часть эстафеты и помогаю команде."],"result":"Общая карта класса «Страна бизнеса»: на ней бизнес-города команд с подписанными бизнесами и ценами товаров в тенге.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Проект (project)","real":"Большое общее дело, которое делают по плану","shown":"Большое общее дело, которое делают по плану","truth":true,"first":"П"},{"term":"Карта","real":"Рисунок местности сверху, где видно города и дороги","shown":"Занятие по правилам","truth":false,"first":"К"},{"term":"Бизнес","real":"Дело, которое делает товары или услуги","shown":"Дело, которое делает товары или услуги","truth":true,"first":"Б"},{"term":"Дорога","real":"Путь, по которому возят товары из города в город","shown":"Рисунок местности сверху, где видно города и дороги","truth":false,"first":"Д"},{"term":"Эстафета","real":"Игра, где участники по очереди передают задание друг другу","shown":"Игра, где участники по очереди передают задание друг другу","truth":true,"first":"Э"},{"term":"Игра (game)","real":"Занятие по правилам","shown":"Путь, по которому возят товары из города в город","truth":false,"first":"И"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Проект (project)","def":"Большое общее дело, которое делают по плану"},{"term":"Карта","def":"Рисунок местности сверху, где видно города и дороги"},{"term":"Бизнес","def":"Дело, которое делает товары или услуги"},{"term":"Дорога","def":"Путь, по которому возят товары из города в город"},{"term":"Эстафета","def":"Игра, где участники по очереди передают задание друг другу"},{"term":"Игра (game)","def":"Занятие по правилам"}],"english":"project — проект; game — игра","concepts":{"head":"Понятия","items":["Проект (project) — общее дело с планом и результатом.","Карта показывает, где находятся города и как их соединяют дороги.","В каждом городе есть бизнес: ферма, завод, кафе, магазин, гостиница."]},"steps":{"head":"Как доделать проект, по шагам","items":["Команда находит свой город на общей карте","Каждый рисует один бизнес на маленьком листочке","Подписывает, что он продаёт и за сколько тенге","Приклеивает к своему городу","Команды рисуют дороги между городами — по ним можно возить товары"]},"scheme":"Большой лист: 4–5 кружков-городов, между ними дороги-линии; в каждом кружке маленькие значки бизнесов с ценниками.","examples":[{"lab":"Казахстан","text":"Из Костаная везут зерно в другие города, из Атырау — нефть; хорошие дороги и железные дороги помогают торговле. В нашем проекте: город «Алтын Алма» продаёт сок по 10 тенге, город «Темір» — гвозди по 5 тенге; если «Алтын Алма» купит 4 упаковки гвоздей, заплатит 20 тенге."},{"lab":"Мир","text":"В Европе города соединены быстрыми поездами, и товары быстро попадают в магазины."}],"mistake":{"myth":"Каждый рисует «свою» карту, и общего проекта не получается","fix":"Напомнить, что карта одна на весь класс, и показать, как бизнесы соединяются дорогами."},"check":[{"q":"Зачем на карте дороги?","a":"Чтобы возить товары и ездить в гости"},{"q":"Что подписываем у бизнеса?","a":"Что продаёт и цену"},{"q":"Почему городам выгодно торговать?","a":"У каждого есть свой товар"}],"kz":{"text":"Сухой порт «Хоргос — Восточные ворота» на границе Казахстана и Китая — место, где контейнеры с товарами перегружают с одних поездов на другие.","link":"дороги и транспорт соединяют города и страны для торговли."},"world":{"text":"Великий Шёлковый путь соединял Китай и Европу, и по нему везли шёлк, специи и посуду через земли современного Казахстана. Сейчас Китай и Европу снова соединяют дороги и железные дороги через нашу страну.","link":""},"fact":"Через территорию Казахстана проходили важные ветви Великого Шёлкового пути; древние города Отрар, Тараз и Туркестан выросли как торговые центры на этом пути.","cards":[{"n":"1","title":"Мой бизнес на карте","lines":["Нарисуй один бизнес своего города: ферма, завод, кафе, магазин или гостиница.","Подпиши: что он продаёт и цену (до 50 тенге).","Пример: «Кафе “Дастархан”: баурсаки — 10 тенге»."],"hand":"Сдать: стикер на карте.","answers":[]},{"n":"2","title":"Эстафета «Бизнесы моего города»","lines":["1) Беги к карте, назови бизнес своего города и что он продаёт.","2) Вернись, передай палочку следующему.","3) Когда все пробежали — нарисуйте дорогу к соседнему городу.","Задача: город А продаёт сок по 10 тенге. Город Б купил 3 сока. Сколько заплатил?"],"hand":"Сдать: выполненная эстафета и дорога на карте.","answers":[["","30 тенге."]]}],"homework":"Сфотографировать или нарисовать по памяти свой город на общей карте и рассказать о нём семье.","support":"Готовые шаблоны значков бизнесов и ценников; задание в паре с другом.","advanced":"Придумать сделку между двумя городами (что меняем и на сколько тенге) и посчитать её.","photo":{"src":"lessons/img/01_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие товары можно возить по дороге между нашими бизнес-городами?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g01-l32.pptx","name":"32. Резерв — повторение, проект или блиц-игра (1 кл).pptx","mb":1.5}}];
